def load() -> pd.DataFrame:
    import glob
    import pandas as pd

    pattern = "data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*.sp3"
    paths = sorted(glob.glob(pattern))
    if not paths:
        raise FileNotFoundError(f"No SP3 files matched pattern: {pattern}")
    return pd.DataFrame({"path": paths})

def process(meanEnergy) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    if meanEnergy is None or len(meanEnergy) == 0:
        return pd.DataFrame({'final': ['nan']})

    v = meanEnergy['meanGeopotentialEnergyJperKg'].iloc[0]
    try:
        v = float(v)
    except Exception:
        v = np.nan

    if not np.isfinite(v):
        return pd.DataFrame({'final': ['nan']})

    return pd.DataFrame({'final': [f"{v:.2f}"]})
